-- SQL 107 · Agente de voz: ritmo da discagem por carteira (Power e Preditivo, V3; PREDITIVO.md P11, Parte 4).
-- O cliente escolhe, por carteira, como a VM disca: Power (razão fixa: linhas por robô livre, 1,0 a 3,0; 1,0 =
-- Progressivo, ninguém atende sem robô) ou Preditivo (razão calculada pela chance de atender, de 1,0 até a razão
-- máxima, com o abandono perto da meta). Fica em credores.discagem › ritmo, com o mesmo histórico de versões, validação
-- e auditoria das outras regras de discagem (salvar_discagem, permissão editar_credores). Padrão: Power 1,0, o
-- comportamento de hoje (nada muda sem a carteira escolher).
--
-- 1. discagem_regras(): o bloco ritmo {modo power|preditivo, razao 1–3, meta_abandono 0,5–3, razao_max 1–3} e a chave
--    em _chaves (gerado de motor/discagem.py › _SUB e PADRAO; tests/test_resubmit.py confere). discagem_erros() valida
--    o bloco pelo caminho genérico dos blocos (nenhuma função de validação muda).
-- 2. discagem_padrao(): + ritmo (o padrão que o site mostra), com o teto de abandono fixo (3%) e a razão máxima da
--    primeira semana do Preditivo (2,0) (= motor/discagem.padrao_site()).
-- As duas funções são recriadas inteiras (a última definição era a do SQL 65; nada mais nelas muda). Nenhuma tabela
-- muda. A VM lê o ritmo por regras_discagem_voz (SQL 65), que já devolve credores.discagem inteiro.
-- Depende do SQL 65. Pode rodar de novo.

-- ================================================================ 1. regras de validação (= motor/discagem.py)
create or replace function public.discagem_regras() returns jsonb
language sql immutable parallel safe as $$
    select '{"_inteiros":{"tentativas_numero_dia":["int",1,10],"tentativas_cliente_dia":["int",1,10],"intervalo_min_minutos":["int",0,1440],"intervalo_ocupado_minutos":["int",0,1440]},"_blocos":{"descanso_nao_atende":{"ativo":"bool","n":["int",1,50],"em_dias":["int",1,60],"descansa_dias":["int",1,365]},"descanso_recusa":{"ativo":"bool","dias":["int",1,365]},"promessa_suspende":{"ativo":"bool","dias_sem_data":["int",1,90]},"inexistente":{"ativo":"bool","modo":["enum","so_voz","invalida"],"so_voz_desde":"data","confirmacoes":["int",1,10],"reteste_dias":["int",1,90],"max_retestes":["int",0,10],"sinal_outros_canais":"bool","aceita_tipo_b":"bool","trava_lote_ativo":"bool","trava_lote_minimo":["int",1,1000000],"trava_lote_fracao":"fracao","trava_lote_relativa":["real",1.0,20.0],"trava_lote_pp_min":"fracao","trava_rota_minimo":["int",1,1000000]},"agente_ia":{"peso_cpc":["real",0.0,2.0],"peso_cpc_sem_identidade":["real",0.0,2.0]},"retorno_agendado":{"ativo":"bool","max_dias":["int",1,60],"sem_hora_dias":["int",0,30],"de":"hora","ate":"hora"},"nao_ligar":{"ativo":"bool"},"chamadas_curtas":{"ativo":"bool","aviso":"fracao","corte_ativo":"bool","corte":"fracao","max_por_numero_dia":["int",1,1000000],"max_total_dia":["int",1,100000000],"abandono_conta":"bool","segundos":["int",1,60],"falha_conta":"bool"},"ritmo":{"modo":["enum","power","preditivo"],"razao":["real",1.0,3.0],"meta_abandono":["real",0.5,3.0],"razao_max":["real",1.0,3.0]}},"por_situacao":{"chaves":["maquina","nao_atendida","ocupado","caixa_postal","desligou_sem_conversar","atendeu_desligou"],"campos":{"max_dia":["int",1,10],"conta_descanso":"bool"}},"falhas_tecnicas":{"chaves":["falha_operadora","sem_credito","falha_rede","indisponivel","bloqueio_originacao","cancelada_discador","abandonada"],"campos":{"aviso":"fracao"}},"por_sinalizacao":{"chaves":["maquina","nao_atendida","ocupado","caixa_postal","desligou_sem_conversar","retorno_agendado","atendeu_desligou","numero_inexistente","pessoa_errada","recado","falha_operadora","falha_rede","indisponivel","cancelada_discador","abandonada"],"campos":{"finaliza":"bool","rediscar":{"ativo":"bool","depois_min":["int",0,600],"max":["int",1,9],"prioridade":["enum","topo","normal","fim"]},"depois":{"acao":["enum","proximo_telefone","proximo_cliente","finaliza"],"espera_min":["int",0,240]},"ate":"hora"}},"modo_discagem":{"campos":{"modo":["enum","vertical","horizontal"],"max_telefones_dia":["int",1,5],"ordem":["enum","certificado","carga","historico"],"telefone_ausente":["enum","proximo","pula"]},"spins":{"quantidade":["int",1,10],"intervalo_min":["int",0,600]},"telefones":["t1","t2","t3","t4","t5","nao_tentado","historico"]},"reciclagem_auto":{"campos":{"ativo":"bool","hora":"hora","sem_contato_pct":["int",10,100]},"excluir":["cpc","promessa","recusa","pessoa_errada","retorno"]},"_chaves":["agente_ia","chamadas_curtas","descanso_nao_atende","descanso_recusa","falhas_tecnicas","horarios","inexistente","intervalo_min_minutos","intervalo_ocupado_minutos","modo_discagem","nao_ligar","por_sinalizacao","por_situacao","promessa_suspende","reciclagem_auto","retorno_agendado","ritmo","tentativas_cliente_dia","tentativas_numero_dia"]}'::jsonb
$$;

-- ================================================================ 2. o padrão MotorCX que o site mostra (= motor/discagem.padrao_site())
create or replace function public.discagem_padrao() returns jsonb
language sql immutable parallel safe as $$
    select '{"tentativas_numero_dia":2,"tentativas_numero_dia_regra_nova":3,"tentativas_cliente_dia":3,"intervalo_min_minutos":120,"intervalo_ocupado_minutos":15,"por_situacao":{"maquina":{"max_dia":2,"conta_descanso":true},"nao_atendida":{"max_dia":2,"conta_descanso":true},"ocupado":{"max_dia":2,"conta_descanso":true},"caixa_postal":{"max_dia":2,"conta_descanso":true},"desligou_sem_conversar":{"max_dia":2,"conta_descanso":false},"atendeu_desligou":{"max_dia":2,"conta_descanso":false}},"falhas_tecnicas":{"falha_operadora":{"aviso":0.15},"sem_credito":{"aviso":0.01},"falha_rede":{"aviso":0.05},"indisponivel":{"aviso":0.2},"bloqueio_originacao":{"aviso":0.01},"cancelada_discador":{"aviso":0.05},"abandonada":{"aviso":0.03}},"por_sinalizacao":{"maquina":{"finaliza":false,"rediscar":{"ativo":true,"depois_min":120,"max":1,"prioridade":"fim"},"depois":{"acao":"proximo_cliente","espera_min":0},"ate":"19:00"},"nao_atendida":{"finaliza":false,"rediscar":{"ativo":true,"depois_min":60,"max":2,"prioridade":"normal"},"depois":{"acao":"proximo_cliente","espera_min":0},"ate":"19:30"},"ocupado":{"finaliza":false,"rediscar":{"ativo":true,"depois_min":15,"max":2,"prioridade":"topo"},"depois":{"acao":"proximo_cliente","espera_min":0},"ate":"19:30"},"caixa_postal":{"finaliza":false,"rediscar":{"ativo":true,"depois_min":120,"max":1,"prioridade":"fim"},"depois":{"acao":"proximo_cliente","espera_min":0},"ate":"19:00"},"desligou_sem_conversar":{"finaliza":false,"rediscar":{"ativo":true,"depois_min":90,"max":1,"prioridade":"normal"},"depois":{"acao":"proximo_telefone","espera_min":0},"ate":"19:00"},"retorno_agendado":{"finaliza":true,"rediscar":{"ativo":false,"depois_min":0,"max":1,"prioridade":"topo"},"depois":{"acao":"finaliza","espera_min":0},"ate":"20:00"},"atendeu_desligou":{"finaliza":false,"rediscar":{"ativo":true,"depois_min":120,"max":1,"prioridade":"normal"},"depois":{"acao":"proximo_cliente","espera_min":0},"ate":"19:00"},"numero_inexistente":{"finaliza":false,"rediscar":{"ativo":false,"depois_min":0,"max":1,"prioridade":"normal"},"depois":{"acao":"proximo_telefone","espera_min":0},"ate":"19:30"},"pessoa_errada":{"finaliza":false,"rediscar":{"ativo":false,"depois_min":0,"max":1,"prioridade":"normal"},"depois":{"acao":"proximo_telefone","espera_min":0},"ate":"19:30"},"recado":{"finaliza":true,"rediscar":{"ativo":false,"depois_min":120,"max":1,"prioridade":"normal"},"depois":{"acao":"proximo_cliente","espera_min":0},"ate":"19:00"},"falha_operadora":{"finaliza":false,"rediscar":{"ativo":true,"depois_min":30,"max":1,"prioridade":"topo"},"depois":{"acao":"proximo_telefone","espera_min":0},"ate":"19:30"},"falha_rede":{"finaliza":false,"rediscar":{"ativo":true,"depois_min":30,"max":1,"prioridade":"topo"},"depois":{"acao":"proximo_telefone","espera_min":0},"ate":"19:30"},"indisponivel":{"finaliza":false,"rediscar":{"ativo":true,"depois_min":30,"max":1,"prioridade":"normal"},"depois":{"acao":"proximo_telefone","espera_min":0},"ate":"19:30"},"cancelada_discador":{"finaliza":false,"rediscar":{"ativo":true,"depois_min":30,"max":1,"prioridade":"topo"},"depois":{"acao":"proximo_telefone","espera_min":0},"ate":"19:30"},"abandonada":{"finaliza":false,"rediscar":{"ativo":true,"depois_min":0,"max":1,"prioridade":"topo"},"depois":{"acao":"proximo_cliente","espera_min":0},"ate":"19:30"}},"sinalizacao_vertical":{"maquina":"proximo_telefone","nao_atendida":"proximo_telefone","caixa_postal":"proximo_telefone"},"modo_discagem":{"modo":"horizontal","max_telefones_dia":1,"ordem":"certificado","telefone_ausente":"proximo","spins":{"quantidade":3,"intervalo_min":120,"regras":[{"spin":1,"telefone":"t1","inicio":null},{"spin":2,"telefone":"t2","inicio":null},{"spin":3,"telefone":"t3","inicio":null}]}},"reciclagem_auto":{"ativo":false,"hora":"16:00","sem_contato_pct":60,"excluir":["cpc","recusa","pessoa_errada","retorno"]},"retorno_agendado":{"max_dias":7},"chamadas_curtas":{"falha_conta":true},"ritmo":{"modo":"power","razao":1.0,"meta_abandono":1.0,"razao_max":3.0,"teto_abandono":3.0,"razao_max_1a_semana":2.0}}'::jsonb
$$;

revoke all on function public.discagem_regras(), public.discagem_padrao() from public, anon;
grant execute on function public.discagem_regras(), public.discagem_padrao() to authenticated, service_role;
